function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fillBleed(0.3);
  // sky
  brush.fill("#5c6b80", 200);
  brush.beginShape(0.3);
  brush.vertex(0, 0); brush.vertex(400, 0); brush.vertex(400, 250); brush.vertex(0, 250);
  brush.endShape(true);
  brush.fill("#f2f2f5", 120);
  brush.circle(300, 120, 30);
  brush.circle(390, 90, 40);
  brush.circle(260, 200, 25);
  // distant sun
  brush.fill("#f7d562", 170);
  brush.circle(200, 150, 50);
  brush.circle(330, 200, 45);
  brush.circle(250, 130, 60);
  // pastels near hills
  const greens = ["#6b7aa0", "#2f3f54", "#3d4d6e"];
  for (let i = 0; i < greens.length; i++) {
    const r = 22 + (i - 1) * 4, b = 180;
    for (let y = 20; y < 330; y += 25 + (y % 3)) {
      for (let x = 10 + r * Math.cos((i * 0.05) + y * 0.05); x < 380; x += 25 + (x % 15)) {
        if (y >= 225 && random() > 0.7) continue;
        const bx = random() < 0.3 ? 1 : 0, a = random() < 0.6 ? 1 : -1;
        brush.fill(greens[i], 190);
        if (bx == 0) {
          if (random() < 0.6) brush.circle(x, y, r + r * a * 0.4);
          else brush.circle(x - r * a * 0.2, y - r * a * 0.3, r + r * a * 0.4);
        }
        else {
          for (let dx = -r; dx < r; dx += r * 0.6 * (a + random()); dx++) {
            for (let dy = 15; dy <= r; dy += r * 0.5 * (a + random())); {
              brush.circle(bx * 13 + x - bx * (dx > 0), y - r * a * 0.5 + dy, r * 0.7);
            }
          }
        }
      }
    }
  }
  // hills
  const cols = ["#2f3f54", "#5c6b80", "#d1495b", "#f5f5f5"];
  for (let i = 0; i < cols.length; i++) {
    const c = cols[i], a = random() < 0.7 ? random() : random() - 0.5;
    const xl = random() < 0.5 ? 110 : 200, xr = random() < 0.5 ? 300 : 340, yb = random() < 0.5 ? 110 : 200;
    for (let y = 180; y < 240; y += 24 + (y % 6)) {
      for (let x = random() * 80; x < yr; x += random() * 15) {
        if (random() > 0.7 && random() < 0.4 && x != xl && x != xr) {
          brush.fill(c, 170);
          brush.circle(x, y, random(3, 7));
        }
      }
    }
  }
}

